begin;
insert into auth.users(id,email,raw_user_meta_data)select ('60000000-0000-4000-8000-00000000000'||n)::uuid,'competition'||n||'@example.test',jsonb_build_object('username','competition_'||n)from generate_series(1,4)n;
insert into public.circles(id,creator_id,name)values('60000000-0000-4000-8000-000000000010','60000000-0000-4000-8000-000000000001','Competition crew');
insert into public.memberships(circle_id,user_id)select '60000000-0000-4000-8000-000000000010',id from public.profiles where username in('competition_1','competition_2','competition_3');
insert into public.challenges(id,circle_id,created_by,rules,rules_hash,status)values('60000000-0000-4000-8000-000000000011','60000000-0000-4000-8000-000000000010','60000000-0000-4000-8000-000000000001','{"title":"Exact rewards","opening":"08:00","cutoff":"09:00","timezone":"UTC","graceDays":0,"penaltyMinor":251,"maxPenaltyMinor":501,"rewardPolicy":"discipline_v1"}','test-hash','active');
insert into public.challenge_participants(challenge_id,user_id,status,rules_hash)select '60000000-0000-4000-8000-000000000011',user_id,'accepted','test-hash'from public.memberships where circle_id='60000000-0000-4000-8000-000000000010';
insert into public.daily_obligations(challenge_id,user_id,local_date,deadline_at)select '60000000-0000-4000-8000-000000000011',p.user_id,((clock_timestamp()at time zone'UTC')::date-10+d),(((clock_timestamp()at time zone'UTC')::date-10+d)+time'09:00')at time zone'UTC'from public.challenge_participants p cross join generate_series(1,5)d where p.challenge_id='60000000-0000-4000-8000-000000000011';
insert into public.evidence_submissions(obligation_id,challenge_id,user_id,note,source,path,status,received_at)
 select o.id,o.challenge_id,o.user_id,'Reading notes','camera',o.user_id||'/'||o.id||'.jpg','accepted',o.deadline_at-interval'30 minutes'from public.daily_obligations o where o.challenge_id='60000000-0000-4000-8000-000000000011'and extract(day from(o.local_date-((clock_timestamp()at time zone'UTC')::date-10)) * interval'1 day')<=case right(o.user_id::text,1)when'1'then 5 when'2'then 4 else 2 end;
create function pg_temp.assert_ok(value boolean,msg text)returns void language plpgsql as $$begin if value is not true then raise exception '%',msg;end if;end;$$;
create function pg_temp.must_fail(q text)returns void language plpgsql as $$declare failed boolean:=false;begin begin execute q;exception when others then failed:=true;end;if not failed then raise exception 'Expected failure: %',q;end if;end;$$;
grant execute on function pg_temp.assert_ok(boolean,text),pg_temp.must_fail(text)to authenticated,anon;
-- Prove unresolved reviews block the worker and cannot become a penalty.
update public.evidence_submissions set status='disputed'where user_id='60000000-0000-4000-8000-000000000001'and obligation_id=(select id from public.daily_obligations where user_id='60000000-0000-4000-8000-000000000001'order by local_date limit 1);
set local role authenticated;
select set_config('request.jwt.claim.sub','60000000-0000-4000-8000-000000000001',true);
select pg_temp.assert_ok(public.stakeup_competition('60000000-0000-4000-8000-000000000011')->>'status'='blocked','Dispute not blocking settlement');
select pg_temp.must_fail('select public.stakeup_competition(''60000000-0000-4000-8000-000000000011'',true)');
select pg_temp.must_fail('select private.process_competition_due()');
select pg_temp.must_fail('insert into public.virtual_settlements(challenge_id,pool_minor,rows_snapshot)values(''60000000-0000-4000-8000-000000000011'',999,''[]'')');
reset role;
select pg_temp.assert_ok(private.process_competition_due()=0,'Worker finalized a dispute');
update public.evidence_submissions set status='accepted'where challenge_id='60000000-0000-4000-8000-000000000011'and status='disputed';
set local role authenticated;
do $$declare r jsonb;again jsonb;hid uuid:='60000000-0000-4000-8000-000000000011';begin
 r:=public.stakeup_competition(hid);perform pg_temp.assert_ok(r->>'status'='ready','Expected ready settlement');
 perform pg_temp.assert_ok((r->>'poolMinor')::integer=752,'Penalty cap or pool mismatch');
 perform pg_temp.assert_ok((r->'rows'->0->>'rewardMinor')::integer=418 and(r->'rows'->1->>'rewardMinor')::integer=334,'Exact proportional allocation mismatch');
 r:=public.stakeup_competition(hid,true);again:=public.stakeup_competition(hid,true);perform pg_temp.assert_ok(r->>'settlementId'=again->>'settlementId','Retry duplicated settlement');
 perform pg_temp.assert_ok((select count(*)=1 from public.virtual_settlements),'Duplicate settlement rows');
 perform pg_temp.assert_ok((select sum(case when kind='penalty'then amount_minor else-amount_minor end)=0 from public.virtual_ledger),'Unbalanced ledger');
 perform pg_temp.assert_ok((select status='completed'from public.challenges where id=hid),'Challenge not completed');
 perform pg_temp.must_fail('update public.virtual_ledger set amount_minor=999');
 perform pg_temp.must_fail(format('select public.stakeup_evidence(''dispute'',%L)',jsonb_build_object('challengeId',hid,'proofId',(select id from public.evidence_submissions limit 1),'reason','Try to reopen settled proof')));
 perform set_config('request.jwt.claim.sub','60000000-0000-4000-8000-000000000002',true);perform public.stakeup_social('leave',jsonb_build_object('circleId','60000000-0000-4000-8000-000000000010'));
 perform set_config('request.jwt.claim.sub','60000000-0000-4000-8000-000000000004',true);
 perform pg_temp.assert_ok((select count(*)=0 from public.virtual_ledger),'Outsider read ledger');perform pg_temp.assert_ok((select count(*)=0 from public.virtual_settlements),'Outsider read results');
 perform pg_temp.must_fail(format('select public.stakeup_competition(%L)',hid));
end;$$;
reset role;
select pg_temp.assert_ok(private.process_competition_due()=0,'Worker duplicated settled challenge');
set local role anon;
select pg_temp.must_fail('select public.stakeup_competition(''60000000-0000-4000-8000-000000000011'')');
reset role;
update public.memberships set left_at=null where circle_id='60000000-0000-4000-8000-000000000010';
insert into public.challenges(id,circle_id,created_by,rules,rules_hash,status)select '60000000-0000-4000-8000-000000000021',circle_id,created_by,rules||'{"graceDays":1}','refund-hash','active'from public.challenges where id='60000000-0000-4000-8000-000000000011';
insert into public.challenge_participants(challenge_id,user_id,status,rules_hash)select '60000000-0000-4000-8000-000000000021',user_id,'accepted','refund-hash'from public.challenge_participants where challenge_id='60000000-0000-4000-8000-000000000011';
insert into public.daily_obligations(challenge_id,user_id,local_date,deadline_at)select '60000000-0000-4000-8000-000000000021',user_id,local_date,deadline_at from public.daily_obligations where challenge_id='60000000-0000-4000-8000-000000000011';
select pg_temp.assert_ok(private.process_competition_due()=1,'Scheduled worker did not finalize ready refund');
select pg_temp.assert_ok((select sum(amount_minor)=1503 from public.virtual_ledger l join public.virtual_settlements s on s.id=l.settlement_id where s.challenge_id='60000000-0000-4000-8000-000000000021'and l.kind='refund'),'No-eligible refund/grace/cap mismatch');
select pg_temp.assert_ok(private.process_competition_due()=0,'Scheduled retry duplicated rewards');
rollback;
